function initSpaceInvaders(canvasId) {
    var canvas = document.getElementById(canvasId);
    if (!canvas) return;
    canvas.width = 500;
    canvas.height = 500;
    var ctx = canvas.getContext('2d');

    var player = {x: canvas.width/2 - 20, y: canvas.height - 40, w: 40, h: 20, speed: 5};
    var keys = {left:false, right:false, up:false, down:false, space:false};

    var playerBullets = [], enemyBullets = [], explosions = [];
    var score = 0, level = 1;
    var enemySpeed = 1, enemyDir = 1, enemyMoveDown = 10;
    var lastEnemyShot = 0, enemyShotInterval = 2000;

    var enemies = [];
    var enemyRows = 5, enemyCols = 9, enemyGap = 10;
    var enemyW = 35, enemyH = 20;

    var playerFireCooldown = 300, lastPlayerFire = 0;
    var gameState = 'playing';

    function createEnemies() {
        enemies = [];
        var totalWidth = enemyCols * (enemyW + enemyGap) - enemyGap;
        var startX = (canvas.width - totalWidth) / 2;
        for (var r = 0; r < enemyRows; r++) {
            for (var c = 0; c < enemyCols; c++) {
                enemies.push({
                    x: startX + c*(enemyW+enemyGap),
                    y: 30 + r*(enemyH+enemyGap),
                    w: enemyW,
                    h: enemyH,
                    alive: true
                });
            }
        }
    }
    createEnemies();

    function resetGame() {
        score = 0;
        level = 1;
        enemySpeed = 1;
        enemyDir = 1;
        createEnemies();
        player.x = canvas.width/2 - player.w/2;
        playerBullets.length = 0;
        enemyBullets.length = 0;
        explosions.length = 0;
        gameState = 'playing';
        lastPlayerFire = 0;
        lastEnemyShot = 0;
    }

    document.addEventListener('keydown', function(e) {
        switch (e.code) {
            case 'ArrowLeft': keys.left = true; break;
            case 'ArrowRight': keys.right = true; break;
            case 'ArrowUp': keys.up = true; break;
            case 'ArrowDown': keys.down = true; break;
            case 'Space': keys.space = true; break;
        }
    });
    document.addEventListener('keyup', function(e) {
        switch (e.code) {
            case 'ArrowLeft': keys.left = false; break;
            case 'ArrowRight': keys.right = false; break;
            case 'ArrowUp': keys.up = false; break;
            case 'ArrowDown': keys.down = false; break;
            case 'Space': keys.space = false; break;
        }
    });

    function rectIntersect(a, b) {
        return !(b.x > a.x + a.w ||
                 b.x + b.w < a.x ||
                 b.y > a.y + a.h ||
                 b.y + b.h < a.y);
    }

    function update() {
        if (gameState !== 'playing') return;

        // Player movement
        if (keys.left && player.x > 0) player.x -= player.speed;
        if (keys.right && player.x + player.w < canvas.width) player.x += player.speed;
        if (keys.up && player.y > 0) player.y -= player.speed;
        if (keys.down && player.y + player.h < canvas.height) player.y += player.speed;

        // Player shooting
        if (keys.space && Date.now() - lastPlayerFire > playerFireCooldown) {
            playerBullets.push({x: player.x + player.w/2 - 2, y: player.y, w: 4, h: 10, dy: -7});
            lastPlayerFire = Date.now();
        }

        // Update bullets
        for (var i = playerBullets.length - 1; i >= 0; i--) {
            var b = playerBullets[i];
            b.y += b.dy;
            if (b.y + b.h < 0) { playerBullets.splice(i,1); continue; }
        }
        for (var i = enemyBullets.length - 1; i >= 0; i--) {
            var b = enemyBullets[i];
            b.y += b.dy;
            if (b.y > canvas.height) { enemyBullets.splice(i,1); continue; }
        }

        // Enemy movement
        var moveSide = false;
        for (var i = 0; i < enemies.length; i++) {
            var e = enemies[i];
            e.x += enemySpeed * enemyDir;
            if (e.x < 0 || e.x + e.w > canvas.width) { moveSide = true; }
        }
        if (moveSide) {
            enemyDir *= -1;
            for (var i = 0; i < enemies.length; i++) {
                enemies[i].y += enemyMoveDown;
            }
        }

        // Enemy shooting
        if (Date.now() - lastEnemyShot > enemyShotInterval) {
            var aliveEnemies = enemies.filter(function(e){return e.alive;});
            if (aliveEnemies.length) {
                var shooter = aliveEnemies[Math.floor(Math.random()*aliveEnemies.length)];
                enemyBullets.push({x: shooter.x + shooter.w/2 - 2, y: shooter.y + shooter.h, w: 4, h: 10, dy: 5});
                lastEnemyShot = Date.now();
            }
        }

        // Collisions
        for (var i = playerBullets.length - 1; i >= 0; i--) {
            var pb = playerBullets[i];
            for (var j = 0; j < enemies.length; j++) {
                var e = enemies[j];
                if (e.alive && rectIntersect(pb, e)) {
                    e.alive = false;
                    explosions.push({x: e.x + e.w/2, y: e.y + e.h/2, r:0});
                    score += 10;
                    playerBullets.splice(i,1);
                    break;
                }
            }
        }
        for (var i = enemyBullets.length - 1; i >= 0; i--) {
            var eb = enemyBullets[i];
            if (rectIntersect(eb, player)) {
                gameState = 'lose';
                break;
            }
        }

        // Check win
        if (enemies.every(function(e){return !e.alive;})) {
            level++;
            enemySpeed += 0.2;
            enemyShotInterval = Math.max(500, enemyShotInterval - 150);
            createEnemies();
            playerBullets.length = 0;
            enemyBullets.length = 0;
        }

        // Check lose enemies reach bottom
        for (var i = 0; i < enemies.length; i++) {
            var e = enemies[i];
            if (e.alive && e.y + e.h >= canvas.height - 20) {
                gameState = 'lose';
                break;
            }
        }

        // Explosions
        for (var i = explosions.length - 1; i >= 0; i--) {
            var ex = explosions[i];
            ex.r += 2;
            if (ex.r > 20) explosions.splice(i,1);
        }
    }

    function draw() {
        ctx.fillStyle = 'black';
        ctx.fillRect(0,0,canvas.width,canvas.height);

        // Draw player
        ctx.fillStyle = 'lime';
        ctx.beginPath();
        ctx.moveTo(player.x + player.w/2, player.y);
        ctx.lineTo(player.x, player.y + player.h);
        ctx.lineTo(player.x + player.w, player.y + player.h);
        ctx.closePath();
        ctx.fill();

        // Draw enemies
        ctx.fillStyle = 'red';
        for (var i = 0; i < enemies.length; i++) {
            var e = enemies[i];
            if (!e.alive) continue;
            ctx.fillRect(e.x, e.y, e.w, e.h);
        }

        // Draw bullets
        ctx.fillStyle = 'yellow';
        for (var i = 0; i < playerBullets.length; i++) {
            var b = playerBullets[i];
            ctx.fillRect(b.x, b.y, b.w, b.h);
        }
        ctx.fillStyle = 'orange';
        for (var i = 0; i < enemyBullets.length; i++) {
            var b = enemyBullets[i];
            ctx.fillRect(b.x, b.y, b.w, b.h);
        }

        // Draw explosions
        for (var i = 0; i < explosions.length; i++) {
            var ex = explosions[i];
            ctx.fillStyle = 'rgba(255,165,0,' + (1 - ex.r/20) + ')';
            ctx.beginPath();
            ctx.arc(ex.x, ex.y, ex.r, 0, Math.PI*2);
            ctx.fill();
        }

        // Draw score and level
        ctx.fillStyle = 'white';
        ctx.font = '16px Arial';
        ctx.fillText('Score: ' + score, 10, 20);
        ctx.fillText('Level: ' + level, 400, 20);

        if (gameState === 'lose') {
            ctx.fillStyle = 'rgba(0,0,0,0.5)';
            ctx.fillRect(0,0,canvas.width,canvas.height);
            ctx.fillStyle = 'white';
            ctx.font = '48px Arial';
            ctx.textAlign = 'center';
            ctx.fillText('Game Over', canvas.width/2, canvas.height/2);
            ctx.font = '24px Arial';
            ctx.fillText('Press Enter to Restart', canvas.width/2, canvas.height/2 + 40);
        }
    }

    function loop() {
        update();
        draw();
        requestAnimationFrame(loop);
    }
    document.addEventListener('keydown', function(e) {
        if (gameState === 'lose' && e.code === 'Enter') {
            resetGame();
        }
    });
    requestAnimationFrame(loop);
}
